/* =====================================================================
   v0.99.2 — déco des murs et des sols (3/4) : objets muraux.
   Repère d'un objet : x le long du mur (-0,5 à 0,5), y vers le haut autour du
   point d'accroche (0,98 par défaut, userData.y pour le changer), z vers la salle.
   ===================================================================== */
const W3=(g,ge,ma,x,y,z,rz,sc)=>{ const m=mesh(ge,ma,x||0,y||0,z||0,false); if(rz) m.rotation.z=rz; if(sc) m.scale.set(sc[0],sc[1],sc[2]); g.add(m); return m; };
const mt=(c,r=.35)=>M(c,{metalness:.7,roughness:r});
const WD='#8a5a34', IRON='#2f3137', BRASS='#c79a52', CREAM='#fffaf0';
// une tige entre deux points du mur
const seg=(g,ma,x1,y1,x2,y2,r,z)=>{ const dx=x2-x1, dy=y2-y1, L=+Math.hypot(dx,dy).toFixed(2)||.01; return W3(g,CY(r,r,L,5),ma,(x1+x2)/2,(y1+y2)/2,z,Math.atan2(-dx,dy)); };
const shelfB=(g,y,w=.8,c=WD)=>{ W3(g,RB(w,.035,.19,.01),M(c,{roughness:.6}),0,y,.095); for(const s of [-1,1]) W3(g,BX(.025,.1,.13),M(shade(c,-.25)),s*(w/2-.1),y-.065,.07); };
// images : textures et matières gardées d'une reconstruction de la salle à l'autre
const ARTC={}, ARTM={};
function artTex(k,w,h,draw){ return ARTC[k]||(ARTC[k]=canvasTex(w,h,draw)); }
function artMat(k,w,h,draw,o){ return ARTM[k]||(ARTM[k]=new THREE.MeshStandardMaterial(Object.assign({map:artTex(k,w,h,draw),roughness:.8},o||{}))); }
function framed(g,k,W,H,fc,draw,o){ o=o||{}; const b=o.b===undefined?.07:o.b, pw=+(W-b).toFixed(3), ph=+(H-b).toFixed(3), tw=o.tw||(W>=H?192:144), th=Math.round(tw*ph/pw);
 W3(g,RB(W,H,.035,.008),M(fc,o.metal?{metalness:.7,roughness:.3}:{roughness:.55}),0,0,.004); W3(g,PL(pw,ph),artMat('pic'+k,tw,th,(x)=>draw(x,tw,th)),0,0,.0225); if(o.y) g.userData.y=o.y; return g; }
function neonSign(g,k,W,H,draw){ W3(g,RB(W+.04,H+.04,.03,.012),M('#1d1b26',{roughness:.6}),0,0,.008); const tw=256, th=Math.round(256*H/W), t=artTex('nz'+k,tw,th,(x)=>{ x.fillStyle='#1d1b26'; x.fillRect(0,0,tw,th); x.lineCap='round'; x.lineJoin='round'; draw(x,tw,th); });
 const m=ARTM['nz'+k]||(ARTM['nz'+k]=new THREE.MeshStandardMaterial({map:t,emissive:'#ffffff',emissiveMap:t,emissiveIntensity:1.15,roughness:.5})); W3(g,PL(W,H),m,0,0,.0245); return g; }
const glow=(x,c,lw,f)=>{ x.strokeStyle=c; x.shadowColor=c; x.shadowBlur=16; x.lineWidth=lw; x.beginPath(); f(); x.stroke(); x.shadowBlur=5; x.strokeStyle='#fff'; x.globalAlpha=.7; x.lineWidth=lw*.35; x.beginPath(); f(); x.stroke(); x.globalAlpha=1; x.shadowBlur=0; };
function clockFace(x,w,bg,ink,acc,label,all){ const c=w/2; x.fillStyle=bg; x.fillRect(0,0,w,w); x.fillStyle=ink; x.strokeStyle=ink; x.textAlign='center'; x.textBaseline='middle'; x.lineCap='butt';
 for(let k=0;k<60;k++){ const a=k/60*6.283, r1=c*(k%5?.9:.84), r2=c*.95; x.lineWidth=k%5?1.5:4; x.beginPath(); x.moveTo(c+Math.sin(a)*r1,c-Math.cos(a)*r1); x.lineTo(c+Math.sin(a)*r2,c-Math.cos(a)*r2); x.stroke(); }
 x.font='700 '+Math.round(w*.13)+'px '+FONT; for(let k=1;k<=12;k++){ const a=k/12*6.283; if(all||k%3===0) x.fillText(String(k),c+Math.sin(a)*c*.68,c-Math.cos(a)*c*.68+2); }
 if(label){ x.font='600 '+Math.round(w*.07)+'px '+FONT; x.fillText(label,c,c+c*.36); }
 const hand=(a,l,lw,col)=>{ x.strokeStyle=col; x.lineWidth=lw; x.lineCap='round'; x.beginPath(); x.moveTo(c-Math.sin(a)*l*.15,c+Math.cos(a)*l*.15); x.lineTo(c+Math.sin(a)*l,c-Math.cos(a)*l); x.stroke(); };
 hand(-1.05,c*.5,7,ink); hand(1.05,c*.74,5,ink); hand(3.6,c*.8,2,acc); dot(x,c,c,6,acc); }
function kilim(x,w,h,P){ x.fillStyle=P[0]; x.fillRect(0,0,w,h); const bands=7, bh=h/bands; for(let j=0;j<bands;j++){ const Y=j*bh, c=P[(j%(P.length-1))+1];
  if(j&1){ x.fillStyle=c; x.fillRect(0,Y+bh*.2,w,bh*.6); x.fillStyle=P[0]; const n=Math.max(2,Math.round(w/(bh*.9))); for(let i=0;i<n;i++){ const X=(i+.5)*w/n; x.beginPath(); x.moveTo(X,Y+bh*.26); x.lineTo(X+bh*.22,Y+bh*.5); x.lineTo(X,Y+bh*.74); x.lineTo(X-bh*.22,Y+bh*.5); x.fill(); } }
  else { x.strokeStyle=c; x.lineWidth=bh*.16; x.lineJoin='miter'; x.beginPath(); const n=Math.max(2,Math.round(w/(bh*.7))); for(let i=0;i<=n;i++) x.lineTo(i*w/n,Y+(i&1?bh*.25:bh*.75)); x.stroke(); } } }

